'use client';

import { ArrowUp, Check, EyeOff, Pin, PinOff, RotateCcw } from 'lucide-react';

// @interlace/question-board v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/question-board
// What changed since: https://ds.interlace.tools/c/question-board#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — QuestionBoard, QuestionAsk and QuestionQueue
 *
 * Questions from the room, ranked by the room. People ask from their phone
 * (`QuestionAsk`), vote up the questions they want answered
 * (`QuestionBoard`), and a moderator approves, pins, answers or hides them
 * (`QuestionQueue`) before anything typed reaches a shared screen.
 *
 * ## Flow
 *
 * | Phase            | Who        | Part                                   |
 * | ---------------- | ---------- | -------------------------------------- |
 * | Asking           | Everyone   | `QuestionAsk`                          |
 * | In review        | Moderator  | `QuestionQueue` (review list)          |
 * | Live and voting  | Everyone   | `QuestionBoard` (vote buttons)         |
 * | Answering now    | Moderator  | `QuestionQueue` pin → board highlights |
 * | Answered, hidden | Moderator  | `QuestionQueue` answer / dismiss       |
 *
 * State lives in your app as a `BoardState` from `question-board-model`;
 * every part takes the ranked questions and sends events back. Run the same
 * `applyBoardEvent` on the host or server: it is the one that counts.
 *
 * ## Anatomy
 *
 *   QuestionBoard                   (section — data-slot="question-board")
 *     ├─ ol (FlipGroup)             (data-slot="question-board-list")
 *     │    └─ li × n                (data-slot="question-board-item", data-pinned, data-mine)
 *     │         ├─ p                (data-slot="question-board-text")
 *     │         └─ Button | span    (data-slot="question-board-vote", aria-pressed; or "question-board-count"
 *     │                              where nobody can vote: a shared screen, or the viewer's own)
 *     └─ p aria-live               (data-slot="question-board-status")
 *
 *   QuestionAsk                     (form — data-slot="question-ask": Textarea, counter, Send, message)
 *   QuestionQueue                   (div — data-slot="question-queue": review and live lists with actions)
 *
 * ## Motion
 *
 * When a vote changes the order, questions glide to their new places
 * (FlipGroup, 400ms, `--ease-move`); the vote count ticks with a short rise
 * of the new number (transform only). The pinned question carries a quiet
 * accent edge. Under reduced motion, everything simply takes its place.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                     |
 * | ---- | ------------------------- | ------------------------------------------------------ |
 * | R4   | Extends native el         | `section` / `form` / `div` props                       |
 * | R6   | data-slot per part        | question-board / -list / -item / -text / -vote / …     |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                      |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                   |
 * | R26  | A11y                      | ordered list; vote is a toggle button with its count in its name |
 */

import * as React from 'react';

import { FlipGroup } from '@/components/ui/effects/flip-group';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import type { BoardEvent, RankedQuestion } from '@/components/ui/games/question-board-model';
import { checkText, visibleLength, type TextRefusal, type TextRules } from '@/components/ui/games/text-safety-model';

export const MIN_VIEWPORT = 320 as const;

// --- QuestionBoard ----------------------------------------------------------------

interface QuestionBoardLabels {
  /** The vote button's name. @default (count, voted) => voted ? `Remove your vote, ${count} votes` : `Vote up, ${count} votes` */
  vote?: (count: number, voted: boolean, formatted: string) => string;
  /** The count where there is no vote button (a shared screen, or the viewer's own). @default (n) => `${n} votes` */
  count?: (count: number, formatted: string) => string;
  /** Beside the pinned question. @default 'Answering now' */
  pinned?: string;
  /** Beside the viewer's own. @default 'Your question' */
  mine?: string;
  /** Under the list. @default (n) => `${n} questions` */
  status?: (count: number, formatted: string) => string;
  /** With no live questions. @default 'No questions yet. Ask the first one.' */
  empty?: string;
}

type QuestionBoardProps = Omit<React.ComponentProps<'section'>, 'children'> & {
  /** Live questions, ranked (`rankQuestions`). */
  questions: readonly RankedQuestion[];
  /** Called when the viewer votes (`true`) or takes a vote back (`false`). Leave out for a shared screen: counts show without buttons. */
  onVote?: (id: string, on: boolean) => void;
  /** `stage` for a shared screen. @default 'default' */
  size?: 'default' | 'stage';
  locale?: string;
  labels?: QuestionBoardLabels;
};

const VOTE: NonNullable<QuestionBoardLabels['vote']> = (n, voted, f) =>
  `${voted ? 'Remove your vote' : 'Vote up'}, ${f} ${n === 1 ? 'vote' : 'votes'}`;

const COUNT: NonNullable<QuestionBoardLabels['count']> = (n, f) => `${f} ${n === 1 ? 'vote' : 'votes'}`;

function VoteCount({ value, formatted }: { value: number; formatted: string }) {
  // Re-keyed on change, so the new number rises into place once.
  return (
    <span
      key={value}
      aria-hidden
      className="motion-safe:animate-in motion-safe:slide-in-from-bottom-1 motion-safe:duration-(--duration-base) motion-safe:ease-enter inline-block tabular-nums"
    >
      {formatted}
    </span>
  );
}

function QuestionBoard({
  questions,
  onVote,
  size = 'default',
  locale,
  labels,
  className,
  ...props
}: QuestionBoardProps) {
  const nf = React.useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const stage = size === 'stage';

  return (
    <section
      data-slot="question-board"
      data-size={size}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-4', className)}
      {...props}
    >
      {questions.length > 0 ? (
        <FlipGroup render={<ol />} data-slot="question-board-list" className="grid gap-3">
          {questions.map((q) => {
            const formatted = nf.format(q.count);
            return (
              <li
                key={q.id}
                data-flip-id={q.id}
                data-slot="question-board-item"
                data-pinned={q.pinned ? '' : undefined}
                data-mine={q.mine ? '' : undefined}
                className={cn(
                  'bg-card relative grid grid-cols-[1fr_auto] items-start gap-4 rounded-lg border p-4',
                  'transition-[border-color,box-shadow] duration-(--duration-medium) ease-enter',
                  q.pinned && 'border-primary shadow-sm',
                  stage && 'p-6',
                )}
              >
                {q.pinned ? (
                  <span aria-hidden className="bg-primary absolute inset-y-3 start-0 w-1 rounded-e-full" />
                ) : null}
                <div className="grid min-w-0 gap-1.5">
                  {q.pinned || q.mine ? (
                    <p className="flex flex-wrap gap-x-3 text-xs font-semibold">
                      {q.pinned ? (
                        <span className="text-primary inline-flex items-center gap-1">
                          <Pin aria-hidden className="size-3.5" />
                          {labels?.pinned ?? 'Answering now'}
                        </span>
                      ) : null}
                      {q.mine ? <span className="text-muted-foreground">{labels?.mine ?? 'Your question'}</span> : null}
                    </p>
                  ) : null}
                  <p
                    data-slot="question-board-text"
                    className={cn('break-words text-pretty', stage ? 'text-2xl leading-snug' : 'text-base')}
                  >
                    {q.text}
                  </p>
                </div>
                {onVote && !q.mine ? (
                  <Button
                    type="button"
                    data-slot="question-board-vote"
                    variant={q.voted ? 'default' : 'outline'}
                    size={stage ? 'lg' : 'default'}
                    aria-pressed={q.voted}
                    aria-label={(labels?.vote ?? VOTE)(q.count, q.voted, formatted)}
                    onClick={() => onVote(q.id, !q.voted)}
                    className="h-auto min-h-11 min-w-14 flex-col gap-0 py-1.5"
                  >
                    <ArrowUp
                      aria-hidden
                      className={cn(
                        'size-4 transition-transform duration-(--duration-fast) ease-enter',
                        q.voted && 'motion-safe:-translate-y-0.5',
                      )}
                    />
                    <VoteCount value={q.count} formatted={formatted} />
                  </Button>
                ) : (
                  <span
                    data-slot="question-board-count"
                    className={cn(
                      'text-muted-foreground flex min-h-11 min-w-14 flex-col items-center justify-center text-sm font-medium',
                      stage && 'text-lg',
                    )}
                  >
                    <ArrowUp aria-hidden className="size-4" />
                    <VoteCount value={q.count} formatted={formatted} />
                    <span className="sr-only">{(labels?.count ?? COUNT)(q.count, formatted)}</span>
                  </span>
                )}
              </li>
            );
          })}
        </FlipGroup>
      ) : null}
      <p data-slot="question-board-status" aria-live="polite" className="text-muted-foreground text-sm">
        {questions.length === 0
          ? (labels?.empty ?? 'No questions yet. Ask the first one.')
          : (labels?.status ?? ((n: number, f: string) => `${f} ${n === 1 ? 'question' : 'questions'}`))(
              questions.length,
              nf.format(questions.length),
            )}
      </p>
    </section>
  );
}
QuestionBoard.displayName = 'QuestionBoard';

// --- QuestionAsk ------------------------------------------------------------------

interface QuestionAskLabels {
  /** @default 'Your question' */
  field?: string;
  /** @default 'Ask' */
  send?: string;
  /** After sending, when the room is moderated. @default 'Sent. A moderator will check it before it shows.' */
  sentReview?: string;
  /** After sending, when it goes live at once. @default 'Sent. It is on the board.' */
  sentLive?: string;
  /** Characters left. @default (n) => `${n} characters left` */
  left?: (remaining: number) => string;
  /** When asking is closed. @default 'Questions are closed for now.' */
  closed?: string;
  refused?: Partial<Record<TextRefusal, string>>;
}

type QuestionAskProps = Omit<React.ComponentProps<'form'>, 'onSubmit' | 'children'> &
  Pick<TextRules, 'blocklist'> & {
    /** Called with the checked text. */
    onAsk?: (text: string) => void;
    /** New questions wait for review (changes the thanks). @default true */
    moderated?: boolean;
    /** @default 200 */
    maxLength?: number;
    disabled?: boolean;
    placeholder?: string;
    labels?: QuestionAskLabels;
  };

const ASK_REFUSED: Record<TextRefusal, string> = {
  empty: 'Type a question first.',
  'too-long': 'That is too long. Try a shorter question.',
  'too-many-words': 'That is too long. Try a shorter question.',
  link: 'Links cannot be sent here.',
  contact: 'Email addresses and phone numbers cannot be sent here.',
  blocked: 'That question cannot be shown here. Try other words.',
};

function QuestionAsk({
  onAsk,
  moderated = true,
  maxLength = 200,
  blocklist,
  disabled = false,
  placeholder,
  labels,
  className,
  ...props
}: QuestionAskProps) {
  const [value, setValue] = React.useState('');
  const [state, setState] = React.useState<
    { kind: 'idle' } | { kind: 'sent' } | { kind: 'refused'; reason: TextRefusal }
  >({
    kind: 'idle',
  });
  const fieldId = React.useId();
  const messageId = React.useId();
  const remaining = maxLength - visibleLength(value);

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (disabled) return;
    const check = checkText(value, { maxLength, blocklist });
    if (!check.ok) {
      setState({ kind: 'refused', reason: check.reason });
      return;
    }
    setValue('');
    setState({ kind: 'sent' });
    onAsk?.(check.text);
  };

  const message = disabled
    ? (labels?.closed ?? 'Questions are closed for now.')
    : state.kind === 'refused'
      ? (labels?.refused?.[state.reason] ?? ASK_REFUSED[state.reason])
      : state.kind === 'sent'
        ? moderated
          ? (labels?.sentReview ?? 'Sent. A moderator will check it before it shows.')
          : (labels?.sentLive ?? 'Sent. It is on the board.')
        : '';

  return (
    <form
      data-slot="question-ask"
      data-state={disabled ? 'closed' : state.kind}
      data-min-viewport={String(MIN_VIEWPORT)}
      noValidate
      onSubmit={submit}
      className={cn('grid gap-2', className)}
      {...props}
    >
      <label htmlFor={fieldId} className="text-sm font-medium">
        {labels?.field ?? 'Your question'}
      </label>
      <Textarea
        id={fieldId}
        value={value}
        rows={3}
        disabled={disabled}
        placeholder={placeholder}
        aria-invalid={state.kind === 'refused' ? true : undefined}
        aria-describedby={messageId}
        onChange={(e) => {
          setValue(e.target.value);
          if (state.kind !== 'idle') setState({ kind: 'idle' });
        }}
      />
      <div className="flex items-center justify-between gap-3">
        <span
          data-slot="question-ask-count"
          className={cn('text-xs tabular-nums', remaining < 0 ? 'text-destructive' : 'text-muted-foreground')}
        >
          {(labels?.left ?? ((n: number) => `${n} characters left`))(remaining)}
        </span>
        <Button type="submit" disabled={disabled}>
          {labels?.send ?? 'Ask'}
        </Button>
      </div>
      <p
        id={messageId}
        data-slot="question-ask-message"
        aria-live="polite"
        className={cn('min-h-5 text-sm', state.kind === 'refused' ? 'text-destructive' : 'text-muted-foreground')}
      >
        {message}
      </p>
    </form>
  );
}
QuestionAsk.displayName = 'QuestionAsk';

// --- QuestionQueue ----------------------------------------------------------------

interface QuestionQueueLabels {
  /** @default 'In review' */
  review?: string;
  /** @default 'On the board' */
  live?: string;
  /** @default 'Answered and hidden' */
  done?: string;
  /** @default 'Nothing waiting.' */
  emptyReview?: string;
  approve?: string;
  dismiss?: string;
  pin?: string;
  unpin?: string;
  answer?: string;
  restore?: string;
  /** Vote count beside a live question. @default (n) => `${n} votes` */
  votes?: (count: number, formatted: string) => string;
}

type QuestionQueueProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  /** Questions waiting for review, oldest first. */
  review: readonly RankedQuestion[];
  /** Live questions, ranked. */
  live: readonly RankedQuestion[];
  /** Answered and dismissed questions, to restore. */
  done?: readonly RankedQuestion[];
  /** Every action sends one event for `applyBoardEvent`. */
  onEvent: (event: BoardEvent) => void;
  locale?: string;
  labels?: QuestionQueueLabels;
};

function QueueRow({ q, children, meta }: { q: RankedQuestion; children: React.ReactNode; meta?: React.ReactNode }) {
  return (
    <li
      data-flip-id={q.id}
      data-slot="question-queue-item"
      data-status={q.status}
      data-pinned={q.pinned ? '' : undefined}
      className={cn('grid gap-2 rounded-md border p-3', q.pinned && 'border-primary')}
    >
      <p className="break-words text-sm">{q.text}</p>
      <div className="flex flex-wrap items-center gap-2">
        {meta ? <span className="text-muted-foreground me-auto text-xs tabular-nums">{meta}</span> : null}
        {children}
      </div>
    </li>
  );
}

function QueueSection({ title, count, children }: { title: string; count: number; children: React.ReactNode }) {
  const id = React.useId();
  return (
    <section aria-labelledby={id} className="grid gap-2">
      <h3 id={id} className="flex items-baseline gap-2 text-sm font-semibold">
        {title}
        <span className="text-muted-foreground text-xs font-normal tabular-nums">{count}</span>
      </h3>
      {children}
    </section>
  );
}

function QuestionQueue({ review, live, done = [], onEvent, locale, labels, className, ...props }: QuestionQueueProps) {
  const nf = React.useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const votes = labels?.votes ?? ((n: number, f: string) => `${f} ${n === 1 ? 'vote' : 'votes'}`);
  return (
    <div
      data-slot="question-queue"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-6', className)}
      {...props}
    >
      <QueueSection title={labels?.review ?? 'In review'} count={review.length}>
        {review.length === 0 ? (
          <p className="text-muted-foreground text-sm">{labels?.emptyReview ?? 'Nothing waiting.'}</p>
        ) : (
          <FlipGroup render={<ul />} className="grid gap-2">
            {review.map((q) => (
              <QueueRow key={q.id} q={q}>
                <Button size="sm" onClick={() => onEvent({ type: 'approve', id: q.id })}>
                  <Check aria-hidden />
                  {labels?.approve ?? 'Approve'}
                </Button>
                <Button size="sm" variant="ghost" onClick={() => onEvent({ type: 'dismiss', id: q.id })}>
                  <EyeOff aria-hidden />
                  {labels?.dismiss ?? 'Dismiss'}
                </Button>
              </QueueRow>
            ))}
          </FlipGroup>
        )}
      </QueueSection>

      <QueueSection title={labels?.live ?? 'On the board'} count={live.length}>
        <FlipGroup render={<ul />} className="grid gap-2">
          {live.map((q) => (
            <QueueRow key={q.id} q={q} meta={votes(q.count, nf.format(q.count))}>
              <Button
                size="sm"
                variant={q.pinned ? 'default' : 'outline'}
                aria-pressed={q.pinned}
                onClick={() => onEvent({ type: 'pin', id: q.pinned ? null : q.id })}
              >
                {q.pinned ? <PinOff aria-hidden /> : <Pin aria-hidden />}
                {q.pinned ? (labels?.unpin ?? 'Unpin') : (labels?.pin ?? 'Pin')}
              </Button>
              <Button size="sm" variant="outline" onClick={() => onEvent({ type: 'answer', id: q.id })}>
                <Check aria-hidden />
                {labels?.answer ?? 'Answered'}
              </Button>
              <Button size="sm" variant="ghost" onClick={() => onEvent({ type: 'dismiss', id: q.id })}>
                <EyeOff aria-hidden />
                {labels?.dismiss ?? 'Hide'}
              </Button>
            </QueueRow>
          ))}
        </FlipGroup>
      </QueueSection>

      {done.length > 0 ? (
        <QueueSection title={labels?.done ?? 'Answered and hidden'} count={done.length}>
          <ul className="grid gap-2">
            {done.map((q) => (
              <QueueRow key={q.id} q={q}>
                <Button size="sm" variant="ghost" onClick={() => onEvent({ type: 'restore', id: q.id })}>
                  <RotateCcw aria-hidden />
                  {labels?.restore ?? 'Back to the board'}
                </Button>
              </QueueRow>
            ))}
          </ul>
        </QueueSection>
      ) : null}
    </div>
  );
}
QuestionQueue.displayName = 'QuestionQueue';

export { QuestionBoard, QuestionAsk, QuestionQueue };
export type {
  QuestionBoardProps,
  QuestionBoardLabels,
  QuestionAskProps,
  QuestionAskLabels,
  QuestionQueueProps,
  QuestionQueueLabels,
};

import { checkText, type TextRefusal, type TextRules } from '@/components/ui/games/text-safety-model';

/**
 * @interlace/ui — question-board-model
 *
 * A room's questions, as one state the host owns: people ask, the room
 * votes the ones it wants answered up, and a moderator decides what reaches
 * the shared screen. Pure, so the host's device, a server and a recap page
 * all agree on the order.
 *
 * ## Lifecycle of a question
 *
 *   ask ──▶ review ──approve──▶ live ──answer──▶ answered
 *             │                  │  ▲
 *             └──dismiss──▶ dismissed ◀──dismiss──┘ │
 *                               └────restore────────┘
 *
 * With `moderated` off, a question skips review and goes live at once.
 * `pin` marks the one live question being answered now (at most one).
 *
 * ## Votes
 *
 * One vote per person per question, toggled with `vote` / `unvote`. Nobody
 * votes for their own question, and only live questions take votes.
 *
 * ## Order
 *
 * `rankQuestions` sorts live questions: the pinned one first, then most
 * votes, then the oldest, so a question that has waited longer wins a tie.
 */

export type QuestionStatus = 'review' | 'live' | 'answered' | 'dismissed';

export interface BoardQuestion {
  id: string;
  text: string;
  /** Who asked. Never shown unless the consumer chooses to. */
  by: string;
  /** When it arrived, in ms (host clock). */
  at: number;
  status: QuestionStatus;
  /** Ids of the people who voted it up. */
  votes: string[];
}

export interface BoardState {
  questions: BoardQuestion[];
  /** New questions wait for review. @default true */
  moderated: boolean;
  /** Taking new questions. */
  open: boolean;
  /** The live question being answered now. */
  pinned: string | null;
  /** Bumped on every change. */
  seq: number;
}

export interface BoardRules extends Pick<TextRules, 'blocklist' | 'allowLinks' | 'allowContact'> {
  /** The longest question, in characters. @default 200 */
  maxLength?: number;
  /** Questions one person may ask. @default 5 */
  maxPerPerson?: number;
}

export type BoardEvent =
  | { type: 'ask'; id: string; text: string; by: string; at: number }
  | { type: 'vote'; id: string; by: string }
  | { type: 'unvote'; id: string; by: string }
  | { type: 'approve'; id: string }
  | { type: 'dismiss'; id: string }
  | { type: 'restore'; id: string }
  | { type: 'answer'; id: string }
  | { type: 'pin'; id: string | null }
  | { type: 'moderate'; on: boolean }
  | { type: 'open'; on: boolean };

export type BoardRejection =
  | TextRefusal
  | 'closed'
  | 'limit'
  | 'duplicate-id'
  | 'unknown'
  | 'not-live'
  | 'own'
  | 'already'
  | 'not-voted'
  | 'wrong-status';

export type BoardResult = { ok: true; state: BoardState } | { ok: false; reason: BoardRejection; state: BoardState };

export function createBoard(init: { moderated?: boolean; open?: boolean } = {}): BoardState {
  return { questions: [], moderated: init.moderated ?? true, open: init.open ?? true, pinned: null, seq: 0 };
}

const FROM: Record<'approve' | 'dismiss' | 'restore' | 'answer', readonly QuestionStatus[]> = {
  approve: ['review'],
  dismiss: ['review', 'live', 'answered'],
  restore: ['dismissed', 'answered'],
  answer: ['live'],
};
const TO: Record<'approve' | 'dismiss' | 'restore' | 'answer', QuestionStatus> = {
  approve: 'live',
  dismiss: 'dismissed',
  restore: 'live',
  answer: 'answered',
};

/** Applies one event, or says why it cannot. The state is never mutated. */
export function applyBoardEvent(state: BoardState, event: BoardEvent, rules: BoardRules = {}): BoardResult {
  const no = (reason: BoardRejection): BoardResult => ({ ok: false, reason, state });
  const next = (patch: Partial<BoardState>): BoardResult => ({
    ok: true,
    state: { ...state, ...patch, seq: state.seq + 1 },
  });
  const find = (id: string) => state.questions.find((q) => q.id === id);
  const replace = (q: BoardQuestion) => state.questions.map((x) => (x.id === q.id ? q : x));

  switch (event.type) {
    case 'ask': {
      if (!state.open) return no('closed');
      if (find(event.id)) return no('duplicate-id');
      const { maxLength = 200, maxPerPerson = 5, ...textRules } = rules;
      const check = checkText(event.text, { ...textRules, maxLength });
      if (!check.ok) return no(check.reason);
      if (state.questions.filter((q) => q.by === event.by).length >= maxPerPerson) return no('limit');
      const q: BoardQuestion = {
        id: event.id,
        text: check.text,
        by: event.by,
        at: event.at,
        status: state.moderated ? 'review' : 'live',
        votes: [],
      };
      return next({ questions: [...state.questions, q] });
    }
    case 'vote':
    case 'unvote': {
      const q = find(event.id);
      if (!q) return no('unknown');
      if (q.status !== 'live') return no('not-live');
      const has = q.votes.includes(event.by);
      if (event.type === 'vote') {
        if (q.by === event.by) return no('own');
        if (has) return no('already');
        return next({ questions: replace({ ...q, votes: [...q.votes, event.by] }) });
      }
      if (!has) return no('not-voted');
      return next({ questions: replace({ ...q, votes: q.votes.filter((v) => v !== event.by) }) });
    }
    case 'approve':
    case 'dismiss':
    case 'restore':
    case 'answer': {
      const q = find(event.id);
      if (!q) return no('unknown');
      if (!FROM[event.type].includes(q.status)) return no('wrong-status');
      return next({
        questions: replace({ ...q, status: TO[event.type] }),
        pinned: state.pinned === q.id ? null : state.pinned,
      });
    }
    case 'pin': {
      if (event.id === null) return next({ pinned: null });
      const q = find(event.id);
      if (!q) return no('unknown');
      if (q.status !== 'live') return no('not-live');
      return next({ pinned: q.id });
    }
    case 'moderate':
      return next({ moderated: event.on });
    case 'open':
      return next({ open: event.on });
  }
}

export interface RankedQuestion extends BoardQuestion {
  /** Votes, as a number. */
  count: number;
  pinned: boolean;
  /** The viewer asked it. */
  mine: boolean;
  /** The viewer voted for it. */
  voted: boolean;
}

/** Questions in one status, ranked: pinned first, then most votes, then oldest. */
export function rankQuestions(
  state: BoardState,
  options: { viewer?: string; status?: QuestionStatus } = {},
): RankedQuestion[] {
  const { viewer, status = 'live' } = options;
  return state.questions
    .filter((q) => q.status === status)
    .map(
      (q): RankedQuestion => ({
        ...q,
        count: q.votes.length,
        pinned: state.pinned === q.id,
        mine: viewer !== undefined && q.by === viewer,
        voted: viewer !== undefined && q.votes.includes(viewer),
      }),
    )
    .sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.count - a.count || a.at - b.at);
}

/** How many questions are in each status. */
export function boardCounts(state: BoardState): Record<QuestionStatus, number> {
  const out: Record<QuestionStatus, number> = { review: 0, live: 0, answered: 0, dismissed: 0 };
  for (const q of state.questions) out[q.status]++;
  return out;
}

export type TextRefusal = 'empty' | 'too-long' | 'too-many-words' | 'link' | 'contact' | 'blocked';

export interface TextRules {
  /** The most characters, as the reader counts them. @default 200 */
  maxLength?: number;
  /** The most words. @default Infinity */
  maxWords?: number;
  /** Words the room refuses. Matched whole, after `foldText`. */
  blocklist?: readonly string[];
  /** Let links through. @default false */
  allowLinks?: boolean;
  /** Let email addresses and phone numbers through. @default false */
  allowContact?: boolean;
}

export type TextCheck = { ok: true; text: string } | { ok: false; reason: TextRefusal };

const SWAPS: Record<string, string> = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '@': 'a', $: 's' };

/** Trims, collapses runs of white space and applies Unicode NFC, so the same word typed twice is the same string. */
export function tidyText(input: string): string {
  return input.normalize('NFC').replace(/\s+/gu, ' ').trim();
}

/** How many characters a reader sees (grapheme clusters, so an emoji or a letter with marks counts once). */
export function visibleLength(text: string): number {
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    let n = 0;
    for (const _ of new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text)) n++;
    return n;
  }
  return Array.from(text).length;
}

/** Splits into words on white space. */
export function wordsOf(text: string): string[] {
  const t = tidyText(text);
  return t ? t.split(' ') : [];
}

/**
 * The form used for matching, never for showing: lowercase, no accents or
 * combining marks (Latin accents, Hebrew points, Arabic short vowels), the
 * common letter swaps folded, and spelled-out letters joined.
 */
export function foldText(input: string): string {
  const base = input
    .normalize('NFKD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/[013457@$]/g, (c) => SWAPS[c] as string);
  // "b a d", "b.a.d", "b-a-d" → "bad": three or more single letters in a row.
  const joined = base.replace(
    /(?<![\p{L}\p{N}])\p{L}(?:[\s.\-_*]+\p{L})(?:[\s.\-_*]+\p{L})+(?![\p{L}\p{N}])/gu,
    (run) => run.replace(/[\s.\-_*]+/g, ''),
  );
  return joined
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/gu, ' ')
    .trim();
}

const LINK =
  /(?:https?:\/\/|www\.)\S+|\b[\p{L}\p{N}-]+\.(?:com|net|org|io|co|me|ly|gg|app|dev|info|xyz|tv|link|site|online)\b/iu;
const EMAIL = /[^\s@]+@[^\s@]+\.[^\s@]+/u;
// Seven or more digits, allowing the usual separators between them.
const PHONE = /(?:\+?\d[\s().-]*){7,}/u;

/** Runs every rule and says the first one the text breaks. */
export function checkText(input: string, rules: TextRules = {}): TextCheck {
  const {
    maxLength = 200,
    maxWords = Number.POSITIVE_INFINITY,
    blocklist,
    allowLinks = false,
    allowContact = false,
  } = rules;
  const text = tidyText(input);
  if (!text) return { ok: false, reason: 'empty' };
  if (visibleLength(text) > maxLength) return { ok: false, reason: 'too-long' };
  if (!allowContact && (EMAIL.test(text) || PHONE.test(text))) return { ok: false, reason: 'contact' };
  if (!allowLinks && LINK.test(text)) return { ok: false, reason: 'link' };
  if (blocklist && blocklist.length > 0 && isBlocked(text, blocklist)) return { ok: false, reason: 'blocked' };
  if (wordsOf(text).length > maxWords) return { ok: false, reason: 'too-many-words' };
  return { ok: true, text };
}

/** True when any whole word, or run of words, of `text` is on the list. */
export function isBlocked(text: string, blocklist: readonly string[]): boolean {
  const hay = ` ${foldText(text)} `;
  const squeezed = ` ${hay.replace(/\s+/g, '')} `;
  for (const raw of blocklist) {
    const needle = foldText(raw);
    if (!needle) continue;
    if (hay.includes(` ${needle} `)) return true;
    // The whole text is the word with its spaces taken out ("ba d").
    if (!needle.includes(' ') && squeezed === ` ${needle} `) return true;
  }
  return false;
}

/**
 * @interlace/ui — text-safety-model
 *
 * The checks a short piece of typed text passes before a room shows it on a
 * shared screen: a word for a word cloud, a question for a Q&A board, a line
 * for an open wall. Pure, so the phone that sends it and the server that
 * receives it run the same rules and agree on the reason.
 *
 * ## What it checks, in order
 *
 *   1. empty            nothing left after trimming
 *   2. too-long         more than `maxLength` characters (counted as the reader sees them)
 *   3. contact          an email address or a phone number
 *   4. link             a URL or a bare domain
 *   5. blocked          a word on the consumer's `blocklist`
 *   6. too-many-words   more than `maxWords` words
 *
 * `blocked` comes before the word count, so "b a d" is refused for what it
 * says, not for having three words.
 *
 * Interlace ships no word list of its own: what is unwelcome depends on the
 * room, its language and its audience, so the consumer passes one. Matching
 * runs on `foldText`, which lowercases, strips accents and marks, folds the
 * common letter swaps (0→o, 1→i, 3→e, 4→a, 5→s, 7→t, @→a, $→s) and joins
 * letters spelled out with spaces or dots ("b a d" → "bad"), so the usual
 * dodges do not get through. Whole words only: a blocked word inside a
 * longer, innocent word is not a match.
 *
 * A filter is one layer, never the only one. Rooms that show typed text to
 * a crowd should also hold it for review (see `question-board-model`).
 */
